  padding: 8px;
}

.jp-Terminal-body .xterm-viewport:focus-visible {
  outline-width: var(--jp-focus-outline-width);
  outline-style: solid;
  outline-color: var(--jp-focus-outline-color);
  outline-offset: calc(var(--jp-focus-outline-width) * -1);
}

[data-term-theme='inherit'] .xterm .xterm-screen canvas {
  border: var(--jp-border-width) solid var(--jp-layout-color0);
}

[data-term-theme='light'] .xterm .xterm-screen canvas {
  border: var(--jp-border-width) solid #fff;
}

